from itertools import combinations

def check_girth(edges, n, min_girth=5):
    """Check if graph has girth >= min_girth (no cycles shorter than min_girth)"""
    # Build adjacency list
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    # Check for triangles (3-cycles)
    for u in range(n):
        for v in adj[u]:
            for w in adj[v]:
                if w != u and w in adj[u]:
                    return False  # Triangle found

    # Check for 4-cycles using BFS
    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        idx = 0
        while idx < len(queue):
            node = queue[idx]
            idx += 1
            for neighbor in adj[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    # Found a cycle
                    cycle_len = dist[node] + dist[neighbor] + 1
                    if cycle_len < min_girth:
                        return False
    return True

def greedy_color(edges, n):
    """Greedy graph coloring, returns number of colors used"""
    adj = {i: set() for i in range(n)}
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    colors = {}
    for node in range(n):
        neighbor_colors = {colors[nb] for nb in adj[node] if nb in colors}
        for c in range(n):
            if c not in neighbor_colors:
                colors[node] = c
                break
    return max(colors.values()) + 1 if colors else 0

